E orgCode, cds.FILE_NUM fileNum, cds.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus, ifnull(cpc.REG_CODE, cds.REG_CODE) regCode, cds.RAISE_TYPE raiseType, cds.IVSTORIENTATION ivstorientation, cds.EXC_FIN_SECTOR excFinSector, cds.IS_SHORT_TERM isShortTerm, cds.SHORT_TERM shortTerm, cds.IS_FREE_REDEM isFreeRedem, cds.CASH_MANA_CATE cashManaCate, cds.YIELD yield, cds.INVEST_FEE_RATE investFeeRate, cds.SUMIT_SEQ sumitSeq, cds.IS_FHXGCP isFhxgcp, cds.PRD_SPEC_PROPERTY prdSpecProperty from CHB_PRD_DECLARE_SUB cds left join CHB_PRDRESIST_CODE cpc on cpc.PRODID = cds.PROD_ID
